# BLOQUE 3: BOTONES REDONDOS
# Acá defino una clase propia de botón, porque Tkinter no trae botones con
# esquinas redondeadas y quería que se vieran más lindos.
# ============================================================================
class RoundedButton(tk.Canvas):
    def __init__(self, parent, width, height, radius, bg_color, fg_color, text="", command=None, hover_color="#3FBFB3"):
        # Heredo de Canvas así puedo dibujar formas dentro.
        super().__init__(parent, width=width, height=height, bg=parent["bg"], highlightthickness=0, bd=0)
        self.width = width
        self.height = height
        self.radius = radius
        self.bg_color = bg_color        # Color normal del botón.
        self.fg_color = fg_color        # Color del texto.
        self.hover_color = hover_color  # Color cuando el mouse pasa por encima.
        self.text = text                # Texto del botón.
        self.command = command          # Función que se ejecuta al clickear.
        self.hover = False              # Bandera para saber si el mouse está arriba o no.

        self._dibujar()                                   # Lo dibujo por primera vez.
        self.bind("<ButtonRelease-1>", self._click)      # Detecto el click.
        self.bind("<Enter>", self._enter)                # Detecto cuando entra el mouse.
        self.bind("<Leave>", self._leave)                # Detecto cuando sale el mouse.

    def _dibujar(self):
        # Dibujo el botón: cuatro arcos en las esquinas y dos rectángulos
        # que rellenan el centro. El color depende de si el mouse está encima.
        self.delete("all")  # Borro lo que había antes.
        w, h, r = self.width, self.height, self.radius
        color = self.hover_color if self.hover else self.bg_color

        # Los cuatro arcos que forman las esquinas redondeadas.
        self.create_arc(0, 0, 2*r, 2*r, start=90, extent=90, fill=color, outline=color)
        self.create_arc(w-2*r, 0, w, 2*r, start=0, extent=90, fill=color, outline=color)
        self.create_arc(w-2*r, h-2*r, w, h, start=270, extent=90, fill=color, outline=color)
        self.create_arc(0, h-2*r, 2*r, h, start=180, extent=90, fill=color, outline=color)

        # Los dos rectángulos que rellenan el medio.
        self.create_rectangle(r, 0, w-r, h, fill=color, outline=color)
        self.create_rectangle(0, r, w, h-r, fill=color, outline=color)

        # El texto centrado.
        self.create_text(w/2, h/2, text=self.text, fill=self.fg_color, font=("Segoe UI", 12, "bold"))

    def _click(self, event):
        # Cuando hacen click, si hay una función asignada, la llamo.
        if self.command:
            self.command()

    def _enter(self, event):
        # Cuando el mouse entra, cambio el cursor y repinto en modo hover.
        self.hover = True
        self.config(cursor="hand2")
        self._dibujar()

    def _leave(self, event):
        # Cuando el mouse sale, vuelvo al color normal.
        self.hover = False
        self._dibujar()

    def set_colors(self, bg, hover, fg=None, parent_bg=None):
        # Uso esto para cambiar los colores en caliente, por ejemplo cuando
        # el usuario activa el modo oscuro.
        self.bg_color = bg
        self.hover_color = hover
        if fg is not None:
            self.fg_color = fg
        if parent_bg is not None:
            self.config(bg=parent_bg)
        self._dibujar()

