# BLOQUE 4: BASE DE DATOS
# Acá me conecto a SQLite y creo las tablas si no existen.
# ============================================================================
conexion = sqlite3.connect("PROYECTO_FINAL_37.db")  # Abro (o creo) el archivo de base.
cursor = conexion.cursor()                           # El cursor sirve para ejecutar queries.
cursor.execute("PRAGMA foreign_keys = ON;")          # Activo el chequeo de claves foráneas.

# Tabla de personas (pacientes): guardo todos los datos personales y la foto.
cursor.execute("""CREATE TABLE IF NOT EXISTS personas(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT NOT NULL,
    apellido TEXT NOT NULL,
    dni INTEGER UNIQUE NOT NULL,
    edad INTEGER,
    fecha_nacimiento TEXT,
    fecha_ingreso TEXT,
    telefono TEXT,
    direccion TEXT,
    contacto_emergencia TEXT,
    telefono_emergencia TEXT,
    obra_social TEXT,
    estado TEXT,
    consentimiento TEXT,
    foto BLOB)""")

# Tabla de entrevistas: cada fila es una sesión hecha por un profesional
# a un paciente. El dni_paciente apunta a personas.dni.
cursor.execute("""CREATE TABLE IF NOT EXISTS entrevistas(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre_profecional TEXT NOT NULL,
    apellido_profecional TEXT,
    dni_profecional TEXT,
    matricula TEXT,
    especialidad TEXT,
    telefono_profecional TEXT,
    email_profecional TEXT,
    activo_profecional TEXT,
    entrevista TEXT NOT NULL,
    dni_paciente INTEGER NOT NULL,
    fecha_entrevista TEXT NOT NULL,
    hora_entrevista TEXT,
    tipo_entrevista TEXT,
    proxima_sesion_entrevista TEXT)""")

# Tabla pdf: acá guardo documentos y también las fotos del editor.
# Cada fila se asocia a un paciente por dni_personas.
conexion.execute("""CREATE TABLE IF NOT EXISTS pdf (id INTEGER PRIMARY KEY AUTOINCREMENT,
nombre TEXT NOT NULL,
formato TEXT NOT NULL,
contenido BLOB NOT NULL,
dni_personas INTEGER)""")

# Tabla recursos: acá guardo cosas fijas de la app, como la imagen de SANCA.
cursor.execute("""CREATE TABLE IF NOT EXISTS recursos(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT UNIQUE NOT NULL,
    contenido BLOB)""")

# Migración: agrego columnas de egreso si la base es vieja y no las tiene. Si ya existen, no hace nada.
cursor.execute("PRAGMA table_info(personas)")
_columnas_personas = {fila[1] for fila in cursor.fetchall()}
for _col, _tipo in (("fecha_egreso", "TEXT"),
                    ("tipo_egreso", "TEXT"),
                    ("motivo_egreso", "TEXT")):
    if _col not in _columnas_personas:
        cursor.execute(f"ALTER TABLE personas ADD COLUMN {_col} {_tipo}")
conexion.commit()

