# ============================================================================
# BLOQUE 14: FUNCIONES AUXILIARES
# Ayudas chicas que uso en varios lados.
# ============================================================================

def comprobar(i_del_for, entry_, orden):
    # Si el entry está vacío, devuelvo el valor viejo (i_del_for[orden]).
    # Lo uso cuando edito algo y el usuario deja un campo en blanco: significa
    # "no lo cambies".
    variable = entry_.get()
    if variable == "":
        return i_del_for[orden]
    else:
        return variable

def normalizar_fecha(texto):
    # Reemplazo separadores de fecha (., -, _) por "/". No toco ":" porque puede
    # ser parte de una hora pegada al lado de la fecha (ej: "03.11.2026 14:30").
    texto = texto.strip()
    for i in string.punctuation:
        if i in (":", "/"):
            continue
        texto = texto.replace(i, "/")
    return texto

def separar_fecha_hora(texto):
    # Si el usuario escribió "03/11/2026 14:30" (fecha y hora pegadas), devuelvo
    # una tupla ("03/11/2026", "14:30"). Si no hay hora, devuelvo (texto, "").
    texto = normalizar_fecha(texto)
    match = re.search(r"\s+(\d{1,2}:\d{2}(?::\d{2})?)\s*$", texto)
    if match:
        hora = match.group(1)
        fecha = texto[:match.start()].strip()
        return fecha, hora
    return texto, ""

def comprobar_fecha(entry_fecha):
    # Normalizo y devuelvo solo la parte de fecha (sin hora).
    fecha, _ = separar_fecha_hora(entry_fecha.get())
    return fecha

def ver_list_entrevist(lista_widget):
    # Refresco la lista de entrevistas. Uso un LEFT JOIN para traer también
    # el nombre y apellido del paciente por si borraron a la persona.
    lista_widget.delete(0, tk.END)
    cursor.execute("""SELECT e.id, e.fecha_entrevista, e.hora_entrevista, e.dni_paciente,
                             e.nombre_profecional, e.apellido_profecional, e.tipo_entrevista,
                             e.especialidad, e.activo_profecional, e.proxima_sesion_entrevista,
                             p.nombre, p.apellido
                      FROM entrevistas AS e
                      LEFT JOIN personas AS p ON p.dni = e.dni_paciente
                      ORDER BY e.id""")
    for i in cursor.fetchall():
        paciente = ""
        if i[10] or i[11]:
            paciente = f" ({i[11] or ''} {i[10] or ''})".strip()
        dato = f"ID: {i[0]} // Fecha: {i[1]} {i[2] or ''} // DNI pac: {i[3]}{paciente} // Prof: {i[4]} {i[5] or ''} // Esp: {i[7] or '-'} // Tipo: {i[6] or '-'} // Estado: {i[8] or '-'}"
        if i[9]:
            dato += f" // Prox: {i[9]}"
        lista_widget.insert(tk.END, dato)

